const fs = await import('node:fs')
const path = await import('node:path')
const dir = '/home/codx-junior/codx-junior/client/src/components/browsers'
for (const name of ['ComputerGridTile.vue', 'ComputerGridView.vue', 'ComputerGridPicker.vue', 'BrowsersSessionManager.vue']) {
  const source = fs.readFileSync(path.join(dir, name), 'utf8')
  const { descriptor, errors } = parse(source, { filename: name })
  if (errors.length) {
    console.log('=== ' + name + ' PARSE ERRORS: ' + errors.map(e => e.message).join(' | '))
    continue
  }
  const id = name
  const script = compileScript(descriptor, { id })
  const template = compileTemplate({
    source: descriptor.template.content,
    filename: name,
    id,
    compilerOptions: { bindingMetadata: script.bindings }
  })
  console.log('=== ' + name + ' template errors: ' + (template.errors.length ? template.errors.map(e => String(e)).join(' | ') : 'none'))
}

