        {
          value: 'kasmweb',
          label: 'Kasmweb',
          icon: 'fa-cubes',
          description: 'KasmVNC · port 6901 · desktops & apps'
        },
        {
          value: 'saved',
          label: 'Saved',
          icon: 'fa-bookmark',
          description: 'Project snapshots · committed containers'
        }
      ]
    }
  },
  watch: {
    provider: {
      immediate: true,
      handler() {
        this.selected = null
        this.selectedTag = ''
        this.tags = []
        this.category = ''
