import { createApp, reactive } from 'vue'
import Modal from './components/Modal.vue'
import PreviewHarness from './PreviewHarness.vue'

// One remembered image, so the wizard's "Recent" row has something to show.
window.localStorage.setItem('codx.computers.recentImages', JSON.stringify([
  {
    id: 'recent:kasmweb/ubuntu-desktop:jammy',
    image: 'kasmweb/ubuntu-desktop:jammy',
    name: 'Ubuntu Desktop',
    provider: 'kasmweb',
    tag: 'jammy',
    live_view: 'kasmvnc',
    kind: 'linux'
  }
]))

const sessions = [
  {
    id: 's1',
    name: 'Ubuntu desktop',
    kind: 'linux',
    status: 'running',
    image: 'lscr.io/linuxserver/webtop:debian-kde'
  },
  {
    id: 's2',
    name: 'Kali tools',
    kind: 'linux',
    status: 'stopped',
    image: 'lscr.io/linuxserver/webtop:ubuntu-kde'
  }
]

const catalog = [
  {
    id: 'lscr.io/linuxserver/webtop:debian-kde',
    provider: 'linuxserver',
    repository: 'lscr.io/linuxserver/webtop',
    image: 'lscr.io/linuxserver/webtop:debian-kde',
    tag: 'debian-kde',
    default_tag: 'debian-kde',
    name: 'Debian KDE',
    description: 'Debian with KDE (Selkies)',
    category: 'Desktops',
    live_view: 'selkies',
    icon_url: null,
    screenshot_url: null,
    tags: ['kde']
  },
  {
    id: 'kasmweb/ubuntu-desktop:jammy',
    provider: 'kasmweb',
    repository: 'kasmweb/ubuntu-desktop',
    image: 'kasmweb/ubuntu-desktop:jammy',
    tag: 'jammy',
    default_tag: 'jammy',
    name: 'Ubuntu Desktop',
    description: 'Kasmweb Ubuntu Jammy (KasmVNC)',
    category: 'Desktops',
    live_view: 'kasmvnc',
    icon_url: null,
    screenshot_url: null,
    tags: ['ubuntu']
  }
]

window.$storex = reactive({
  ui: {
    isMobile: false,
    addNotification() {},
    notify() {}
  },
  projects: { activeProject: { project_name: 'codx-junior' } },
  api: {
    computers: {
      async images() {
        return { images: catalog }
      },
      async imageTags() {
        return { tags: [{ name: 'jammy' }, { name: 'focal' }] }
      },
      async savedComputers() {
        return { computers: [] }
      },
      async desktopSizes() {
        return { presets: [] }
      }
    }
  },
  browsers: {
    sessions,
    allSessions: sessions,
    selectedSessionId: null,
    isLoading: false,
    hasError: false,
    errorMessage: '',
    isGridView: false,
    gridLayout: 'grid',
    gridSessionIds: [],
    gridActiveId: null,
    gridSessions: [],
    pendingLibraryImage: null,
    showNewSessionForm: true,
    loadSessions() {},
    toggleNewSessionForm() {},
    clearPendingLibraryImage() {},
    selectSession() {},
    clearSelection() {},
    setViewMode(mode) {
      this.isGridView = mode === 'grid'
    },
    setGridLayout(layout) {
      this.gridLayout = layout
    },
    setGridSessions() {},
    addGridSession() {},
    removeGridSession() {},
    toggleGridSession() {},
    setGridActive() {},
    openSingleSession() {},
    async deleteSession() {},
    async runSession() {},
    startEditingSession() {}
  }
})

const app = createApp(PreviewHarness)
app.component('modal', Modal)
app.mount('#app')

request.script:
return (() => {
  const sidebar = document.querySelector('#sidebar')
  const stage = document.querySelector('#stage')
  const sidebarText = sidebar ? sidebar.innerText : ''
  const result = {
    overlay: !!document.querySelector('.vite-error-overlay'),
    sidebarButtons: sidebar ? sidebar.querySelectorAll('button').length : -1,
    hasViewLabel: sidebarText.includes('View'),
    hasSingle: sidebarText.includes('Single'),
    hasGrid: sidebarText.includes('Grid'),
    stageHeight: stage ? Math.round(stage.getBoundingClientRect().height) : -1,
    stageText: stage ? stage.innerText.trim() : '',
    modalCount: document.querySelectorAll('.modal').length,
    modalText: (document.querySelector('.modal-box') || {}).innerText ? document.querySelector('.modal-box').innerText.slice(0, 400) : ''
  }
  return result
})()

return (() => {
  const sidebar = document.querySelector('#sidebar')
  const stage = document.querySelector('#stage')
  const sidebarText = sidebar ? sidebar.innerText : ''
  return {
    overlay: !!document.querySelector('vite-error-overlay'),
    hasApp: !!document.querySelector('#app'),
    sidebarButtons: sidebar ? sidebar.querySelectorAll('button').length : -1,
    hasViewLabel: sidebarText.includes('View'),
    hasSingle: sidebarText.includes('Single'),
    hasGrid: sidebarText.includes('Grid'),
    stageHeight: stage ? Math.round(stage.getBoundingClientRect().height) : -1,
    stageText: stage ? stage.innerText.trim() : '',
    modalCount: document.querySelectorAll('.modal').length,
    sidebarText: sidebarText.slice(0, 400)
  }
})()

